\label{thm:israel}
\begin{romanenumerate}
\item ${\mathfrak A}$ is simple, i.e., has no non-trivial two-sided ideals.
\item Any KMS state on ${\mathfrak A}$ is faithful. 
\item If two $C^\ast$-dynamics $\tau_1$ and $\tau_2$ on ${\mathfrak A}$
share a $\beta$-KMS state, then $\tau_1=\tau_2$. 
\end{romanenumerate}

\label{thm:stein}
Suppose that for some $\delta >0$ the expression
\begin{equation}
[0,1+\delta]\ni \alpha\mapsto
e(\alpha)\coloneq\lim_{\{\Lambda\}}\tfrac1{|\Lambda|}\log\mathop{\mathrm{tr}}\nolimits_{{\mathcal H}_\Lambda}(\nu_\Lambda^\alpha\mu_\Lambda^{1-\alpha})
\label{eq:lim}
\end{equation}
defines a continuous function $e$, differentiable on $(0,1]$ and such that $(\partial^+e)(0)<e^\prime(1)$.
\footnote{We denote by $\partial^\mp$ the left/right derivative.}
Then the quantum Stein Lemma holds for the pair $(\nu,\mu)$.

\label{prop:vanish_on_average}
For $A\in{\mathfrak A}_\mathrm{sa}$, the following conditions are equivalent. 
\begin{romanenumerate}
\item $A\in{\mathfrak I}$.
\item $\displaystyle\lim_{\{\Lambda\}}\|m_\Lambda(A)\|=0$.
\item $\varphi(A)=0$ for all $\varphi\in{\mathfrak A}^\ast_I$.
\item $\omega(A)=0$ for all $\omega\in{\mathcal S}_\mathrm{I}$.
\end{romanenumerate}

\label{prop:seminorm_interpretation}
For any $A\in{\mathfrak A}_\mathrm{sa}$, one has
\begin{gather}
\lim_{\{\Lambda\}}\left\|m_\Lambda(A)\right\|=\|A\|_{{\mathfrak A}_\mathrm{sa}/{\mathfrak I}},\label{eq:overI}\\
\lim_{\{\Lambda\}}\left\|m_\Lambda(A)\right\|_{{\mathfrak A}_\mathrm{sa}/{\mathbbm R}}=\|A\|_{{\mathfrak A}_\mathrm{sa}/({\mathfrak I}+{\mathbbm R})}\label{eq:overIplusR}.
\end{gather}

\label{prop:ru-R}
\begin{romanenumerate}
\item $R:{\mathcal B}_\mathrm{b}\to{\mathfrak A}_\mathrm{sa}$ is a surjective linear contraction such that $R({\mathcal B}_\mathrm{f})={\mathfrak A}_\mathrm{sa}\cap{\mathfrak A}_\mathrm{loc}$.
\item For all $\Phi\in{\mathcal B}_\mathrm{b}$, $R(\Phi)\equiv E(\Phi)\,(\mathrm{mod}\,{\mathfrak I})$.
\item The map $\hat R:{\mathcal B}_\mathrm{b}/\mathop{\mathrm{Ker}}\nolimits(R)\ni\Phi+\mathop{\mathrm{Ker}}\nolimits(R)\mapsto R(\Phi)\in{\mathfrak A}_\mathrm{sa}$ is an isometric isomorphism.
\end{romanenumerate}

\label{thm:RuIso}
The Ruelle map $R$ induces the isometric isomorphisms 
\begin{equation}
{\mathcal B}_\mathrm{b}/{\mathcal I}\to{\mathfrak A}_\mathrm{sa}/{\mathfrak I},
\label{eq:hatR}
\end{equation}
and
$$
{\mathcal B}_\mathrm{b}/({\mathcal I}+{\mathcal R})\to{\mathfrak A}_\mathrm{sa}/({\mathfrak I}+{\mathbbm R}).
$$

\label{thm:Gibbs}
Assume that $\Phi\in{\mathcal B}_\mathrm{b}$.
\begin{romanenumerate}
\item {\bf Specific energy.}
For any $\omega\in{\mathcal S}_\mathrm{I}$, one has 
\[
\lim_{\{\Lambda\}}\frac1{|\Lambda|}\omega(H_\Lambda(\Phi))={\mathcal e}_\Phi(\omega).
\]
\item {\bf Pressure.}
The limit 
\begin{equation}
P(\Phi)\coloneq\lim_{\{\Lambda\}}\frac1{|\Lambda|}\log\mathop{\mathrm{tr}}\nolimits_{{\mathcal H}_\Lambda}\left(\mathrm{e}^{-H_\Lambda(\Phi)}\right)
\label{eq:PDef}
\end{equation}
exists and is finite. The map ${\mathcal B}_\mathrm{b}\ni\Phi \mapsto P(\Phi)$ is convex,
continuous, and satisfies
\[
|P(\Phi)-P(\Psi)|\leq\|\Phi-\Psi\|_\mathrm{b}.
\]
\item {\bf Variational principle.} The pressure $P$ satisfies
\begin{equation}
P(\Phi)=\sup_{\omega\in{\mathcal S}_\mathrm{I}}\left(s(\omega)-{\mathcal e}_\Phi(\omega)\right).
\label{eq:GibbsPrince}
\end{equation}
The set of maximizers
\[
{\mathcal S}_\mathrm{eq}(\Phi)\coloneq\left\{\omega\in{\mathcal S}_\mathrm{I}\mid P(\Phi)=s(\omega)-{\mathcal e}_\Phi(\omega)\right\}
\]
is a non-empty, convex, compact subset of ${\mathcal S}_\mathrm{I}$. It is a Choquet simplex
and a face of ${\mathcal S}_\mathrm{I}$. Its elements are called \textbf{equilibrium states}
for the interaction $\Phi$ and its extreme points are $\varphi$-ergodic.

\item {\bf Dual variational principle.} For any $\omega\in{\mathcal S}_\mathrm{I}$, one has
\begin{equation} 
s(\omega)=\inf_{\Psi\in{\mathcal B}_\mathrm{b}}\left(P(\Psi)+{\mathcal e}_\Psi(\omega)\right). 
\label{eq:dual-var}
\end{equation}
\end{romanenumerate}

\label{prop:Pafin}
Suppose that $\Phi,\Psi\in{\mathcal B}_\mathrm{b}$. Then the following statements are equivalent.
\begin{romanenumerate}
\item For any $t\in[0,1]$, 
\[
P((1-t)\Phi+t\Psi)=(1-t)P(\Phi)+tP(\Psi).
\]
\item ${\mathcal S}_\mathrm{eq}(\Phi)\cap{\mathcal S}_\mathrm{eq}(\Psi)\neq\emptyset$.
\end{romanenumerate}

\label{prop:weakGibbs_are_eq}
For $\Phi,\Psi\in{\mathcal B}_\mathrm{b}$, the following hold:
\begin{romanenumerate}
\item $\omega\in{\mathcal S}_\mathrm{lwg}(\Phi)\Leftrightarrow
\displaystyle\limsup_{\{\Lambda\}}\frac1{|\Lambda|}\|\log\omega_\Lambda-\log\omega_{\Phi,\Lambda}^c\|=0$.
\item ${\mathcal S}_\mathrm{wg}(\Phi)\subset{\mathcal S}_\mathrm{lwg}(\Phi)\subset{\mathcal S}_\mathrm{eq}(\Phi)$.
\item Suppose that $\omega\in{\mathcal S}_\mathrm{lwg}(\Phi)$. Then for any $\nu\in{\mathcal S}_\mathrm{I}$, 
\begin{equation}
s(\nu|\omega)=-s(\nu)+{\mathcal e}_\Phi(\nu)+P(\Phi).
\label{eq:def-rp}
\end{equation}
In particular $s(\nu|\omega)=0$ iff $\nu\in{\mathcal S}_\mathrm{eq}(\Phi)$.
\end{romanenumerate}

\label{WG}\label{LWG}\label{R}
\begin{romanenumerate}
\item A set ${\mathcal B}\subset{\mathcal B}_\mathrm{b}$ has the property \textbf{(WG)} if ${\mathcal S}_\mathrm{wg}(\Phi)={\mathcal S}_\mathrm{eq}(\Phi)$ for any $\Phi\in{\mathcal B}$.
\item A set ${\mathcal B}\subset{\mathcal B}_\mathrm{b}$ has the property \textbf{(LWG)} if ${\mathcal S}_\mathrm{lwg}(\Phi)={\mathcal S}_\mathrm{eq}(\Phi)$ for any $\Phi\in{\mathcal B}$.
\item A set ${\mathcal B}\subset{\mathcal B}_\mathrm{b}$ has the property \textbf{(R)} if, for any $\Phi\in{\mathcal B}$ and any $\omega\in{\mathcal S}_\mathrm{eq}(\Phi)$,
the pair $(\omega,\Phi)$ is regular. 
\end{romanenumerate}

\label{prop:BsStuf}
If $\Phi\in{\mathcal B}_\mathrm{s}$, then the following hold. 
\begin{romanenumerate}

\item $\|W_\Lambda(\Phi)\|\le|\Lambda|\,\|\Phi\|_\mathrm{s}$.
\item $\displaystyle\lim_\Lambda\frac1{|\Lambda|}\|W_\Lambda(\Phi)\|=0$.
\item $\displaystyle\lim_{\{\Lambda\}}\left\|\frac1{|\Lambda|}U_\Lambda(\Phi)-m_\Lambda(E(\Phi))\right\|=0$.
\end{romanenumerate}

\label{thm:jpt-o}
Suppose that $\omega\in{\mathcal S}_\mathrm{eq}(\Psi)$ for some $\Psi\in{\mathcal B}_\mathrm{b}$. Then, for any
$\omega_+\in\Sigma_+(\omega,\Phi)$,
\begin{romanenumerate}
\item ${\mathcal e}_\Psi(\omega_+)\ge{\mathcal e}_\Psi(\omega)$.
\item If ${\mathcal S}_\mathrm{eq}(\Psi)=\{\omega\}$, then ${\mathcal e}_\Psi(\omega_+)>{\mathcal e}_\Psi(\omega)$. 
\end{romanenumerate}

\label{thm:GibbsII}
\begin{romanenumerate}
\item There is a unique $e_0\in(e_\mathrm{min},e_\mathrm{max})$ such that 
${\mathcal s}(e_0)=\max\{{\mathcal s}(e)\mid e\in{\mathbbm R}\}=\log\mathop{\mathrm{dim}}\nolimits{\mathcal H}$, the function ${\mathcal s}$ being
monotone increasing on the interval $[e_\mathrm{min},e_0]$ and monotone decreasing
on the interval $[e_0,e_\mathrm{max}]$.
\item The parametric form of the Gibbs variational principle~\eqref{eq:AizLieb1}
admits the following dual principle: For any $e\in(e_\mathrm{min},e_\mathrm{max})$, 
\begin{equation}
{\mathcal s}(e)=\min_{\beta\in{\mathbbm R}}\left({\mathcal p}(\beta)+\beta e\right),
\label{eq:smalldualGibbs}
\end{equation}
the minimum being achieved at $\beta=\beta_\ast(e)$, i.e.,
\begin{equation}
{\mathcal s}(e)={\mathcal p}(\beta_\ast(e))+\beta_\ast(e)e.
\label{eq:AizLieb}
\end{equation}
Moreover, if $\nu\in{\mathcal S}_\mathrm{I}$ is such that ${\mathcal e}_\Phi(\nu)=e$, then ${\mathcal s}(e)=s(\nu)$ iff
$\nu\in{\mathcal S}_\mathrm{eq}(\beta_\ast(e)\Phi)$.
\end{romanenumerate}

\label{prop:st-pres}
Let $\omega_\mathrm{eq}\in{\mathcal S}_\mathrm{eq}(\omega,\Phi)$. 
\begin{romanenumerate} 
\item $s(\omega)<s(\omega_\mathrm{eq})$. 
\item                                                                        
For any $\omega_+ \in\Sigma_+(\omega, \Phi)$, $s(\omega_+)\leq s(\omega_\mathrm{eq})$
with equality iff $\omega_+\in{\mathcal S}_\mathrm{eq}(\omega,\Phi)$.
\end{romanenumerate}

Suppose that $(\Phi, \Psi)$ has the \preSD{} property and that for all $s,t\in{\mathbbm R}$, 
\begin{equation}
\tau_\Phi^t \circ \tau_\Psi^s=\tau_\Psi^s\circ \tau_\Phi^t.
\label{eq:DynCommut}
\end{equation}
Then $\Psi$ is $\tau_\Phi$-invariant, i.e., $[\Psi]\in{\mathfrak C}(\Phi)$.
\label{thm:main1-const}

\label{prop:hc}
Suppose that $(\Phi,\Psi)$ has the \preSD{} property, that $[\Psi]\in{\mathfrak C}(\Phi)$, and that $\Psi_t\in{\mathcal B}_\mathrm{sd}$ for $t$ in
a neighborhood of\, $0$. Then for all $s,t\in{\mathbbm R}$, 
\begin{equation}
\tau_\Phi^t\circ\tau_\Psi^s=\tau_\Psi^s\circ\tau_\Phi^t.
\label{eq:DynCommute}
\end{equation}

\label{SDplus}
We say that a pair $(\Phi,\Psi)$ has the \textbf{(SD+)} property if it has the \preSD{} property and, in addition,
for $t$ in a neighborhood of $0$, ${\mathfrak A}_\mathrm{loc}$ is a core for $\delta_t$.

\label{thm:jpst}
Suppose that $\Phi\in{\mathcal B}^{\oslash^{r}}$ for some $r>2d$ and that $\Psi\in{\mathcal B}_\mathrm{sd}$.
Then the following hold.
\begin{romanenumerate}
\item For every $t\in{\mathbbm R}$, ${\mathfrak A}_\mathrm{loc}$ is a core for the generator of
$\tau_\Phi^{-t}\circ\tau_\Psi\circ\tau_\Phi^t$.
\item If, in addition, $\Psi\in{\mathcal B}^{\oslash^{s}}$ for some $s>d$, then the pair
$(\Phi,\Psi)$ has the \preSDplus{} property. In this case, the properties
entering its definition hold for every $t\in{\mathbbm R}$.
\end{romanenumerate}

Suppose that $\Phi,\Psi\in{\mathcal B}_\mathrm{sd}$. Then
\begin{equation}
[\Psi]\in{\mathfrak C}(\Phi)\quad\Leftrightarrow\quad [\Phi]\in{\mathfrak C}(\Psi).
\label{eq:t-nice}
\end{equation}

\label{prop:wd-pres}
Suppose that $\tau_\Phi$ preserves the specific entropy, and let
$(\rho,\Psi)\in{\mathcal S}_\mathrm{I}\times{\mathcal B}_\mathrm{b}$ be a regular pair. Then the following
statements are equivalent.
\begin{romanenumerate}
\item $s(\nu \circ \tau_\Phi^t|\rho)=s(\nu|\rho)$ for all $\nu\in{\mathcal S}_\mathrm{I}$
and $t\in{\mathbbm R}$.
\item $[\Psi]\in{\mathfrak C}(\Phi)$.
\end{romanenumerate}

\label{thm:main-cm}
Let $\omega_+\in\Sigma_+(\omega,\Phi)\cap{\mathcal S}_\mathrm{eq}(\Psi_+)$ for some $\Psi_+\in{\mathcal B}_\mathrm{sd}$.
If the pair $(\Phi,\Psi_+)$ has the \preSD{} property, then $[\Psi_+]\in{\mathfrak C}(\Phi)$.

\label{thm-jpst2}
Suppose that $\Phi\in{\mathcal B}_\mathrm{f}$ and let $\omega_+\in\Sigma_+(\omega,\Phi)\cap{\mathcal S}_\mathrm{eq}(\Psi_+)$. 
\begin{romanenumerate}
\item If $\|\Psi_+\|_r<r$ for some $r>0$, then $[\Psi_+]\in{\mathfrak C}(\Phi)$.
\item The same conclusion holds if $d=1$ and $\Psi_+\in{\mathcal B}_\mathrm{f}$. 
\end{romanenumerate}

\label{def:ae}
The pair $(\omega,\Phi)$ has the property of \textsl{approach to equilibrium} if
\begin{romanenumerate}
\item the limit
\[
\omega_+=\mathop{\mathrm{w^\ast-lim}}\limits_{T\to\infty}\frac1T\int_0^T\omega\circ\tau_\Phi^t\mathrm{d} t
\]
exists;
\item $\omega_+\in{\mathcal S}_\mathrm{phys}(\Phi)$.
\end{romanenumerate}

\label{thm:main-ate}
Suppose that $\beta_\mathrm{eq} \Phi\in{\mathcal B}_\mathrm{R}$ and that there exists
$\omega_\mathrm{eq}\in{\mathcal S}_\mathrm{eq}(\omega,\Phi)$ such that
\[
\omega(C)=\omega_\mathrm{eq}(C)
\]
provided $[C]\in\mathfrak{C}_\mathrm{phys}(\Phi)$. Let $\omega_+\in\Sigma_+(\omega,\Phi)$. Then the following statements are
equivalent:
\begin{romanenumerate}
\item $\omega_+\in{\mathcal S}_\mathrm{eq}(\omega,\Phi)$;
\item $\omega_+\in{\mathcal S}_\mathrm{phys}(\Phi)$.
\end{romanenumerate}
